; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: neogeo (SNK Neo Geo (68000)), starts in turbo mode
; ============================================================

			org 0

NTC_RAMEND	equ $10C000		; the end of the RAM the variables and arrays are in (;@ramend)
NTC_A16ADD	equ $110000		; (;@a16) added to a 16 bit address once sign extended: where the RAM's 64K is (0: $FF8000 on, the Mega Drive)
NTC_A16		macro			; an address register loaded from a 16 bit address (movea.w): to the RAM it means
			ifne NTC_A16ADD
			adda.l #NTC_A16ADD, \1
			endif
			endm
;## ntc_md_vectors ntc_ng_boot
; the cartridge's vectors (the BIOS's routines for the exceptions, as every cartridge has them)
; and the Neo Geo header (the compiler puts this first, at 0)
			dc.l $0010F300				; the supervisor stack
			dc.l $00C00402				; reset: the BIOS
			dc.l $00C00408, $00C0040E, $00C00414, $00C0041A	; bus, address, illegal, zero divide
			dc.l $00C0041A, $00C0041A, $00C0041A, $00C00420	; CHK, TRAPV, privilege, trace
			dc.l $00C00426, $00C00426					; line 1010, 1111
			dcb.l 3, $FFFFFFFF			; 12-14
			dc.l $00C0042C				; 15 uninitialised interrupt
			dcb.l 8, $FFFFFFFF			; 16-23
			dc.l $00C00432				; 24 spurious
			dc.l ntc_ng_vbl				; 25 level 1: VBlank
			dc.l ntc_ng_timer			; 26 level 2: the timer
			dc.l ntc_ng_rte				; 27 level 3
			dcb.l 4, ntc_ng_rte			; 28-31
			dcb.l 32, $FFFFFFFF			; 32-63
; the header ($100): test/ngbuild.js puts in the NGH number and the name
			dc.b "NEO-GEO", 0
			dc.w $0C1C					; $108 the NGH number (3100: not $999, which the emulators take for V-Liner)
			dc.l $00100000				; $10A the program's size
			dc.l $0010E800				; $10E an MVS's backup RAM (none used)
			dc.w 0						; $112 its size
			dc.b 1						; $114 the eye-catcher: the game's (USER request 1, which goes straight back)
			dc.b 0						; $115 its first tile
			dc.l ntc_ng_dip, ntc_ng_dip, ntc_ng_dip	; $116 the soft DIPs: Japan, the US, Europe
			dc.w $4EF9					; $122 USER: jmp abs.l (written out: 6 bytes each, at
			dc.l ntc_ng_user			;      the header's fixed places)
			dc.w $4EF9					; $128 PLAYER_START
			dc.l ntc_ng_rts
			dc.w $4EF9					; $12E DEMO_END
			dc.l ntc_ng_rts
			dc.w $4EF9					; $134 COIN_SOUND
			dc.l ntc_ng_rts
			dcb.b 70, $FF				; $13A
			dc.w 0						; $180
			dc.l ntc_ng_scode			; $182 the security code
ntc_ng_scode:
			dc.w $7600, $4A6D, $0A14, $6600, $003C, $206D, $0A04, $3E2D
			dc.w $0A08, $13C0, $0030, $0001, $3210, $0C01, $00FF, $671A
			dc.w $3028, $0002, $B02D, $0ACE, $6610, $3028, $0004, $B02D
			dc.w $0ACF, $6606, $B22D, $0AD0, $6708, $5088, $51CF, $FFD4
			dc.w $3607, $4E75, $206D, $0A04, $3E2D, $0A08, $3210, $E049
			dc.w $0C01, $00FF, $671A, $3010, $B02D, $0ACE, $6612, $3028
			dc.w $0002, $E048, $B02D, $0ACF, $6606, $B22D, $0AD0, $6708
			dc.w $5888, $51CF, $FFD8, $3607, $4E75
ntc_ng_dip:	dc.b "NTC BASIC       "		; the name the BIOS shows (16)
			dc.b $FF, $FF, $FF, $FF		; no time DIPs
			dc.b $FF, $FF				; no number DIPs
			dcb.b 10, 0					; no choice DIPs
			even

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI, 3 ADM-3A, 4 Televideo (CP/M)
NTC_TERM_RT	equ 0		; 1: the program calls StdIO.SetTerminal (the terminal is chosen while it runs)
NTC_STRMAX	equ 40		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs
NTC_ROMLIB	equ 0		; 1 = the library is the keyword ROM (Library: ROM; ntcRomAsm builds it)
NTC_WINHOLE	equ 0		; 1 = the program is built round an Option Reserve range over the window #4000-#7FFF
NTC_WINPAGED	equ 0		; 1 = page 0 code may sit under the window (Option Memory Paged, not Reserved): the Memory class never hands out page 1 (main RAM's own #4000-#7FFF) when the code reaches past #4000
NTC_BUFSIZE	equ 2048		; the library's buffer (ntc_buf: FileSystem, Memory.Copy): Option Buffer
NTC_ISLN	equ 1		; interrupt classes (Option Class Interrupt): the slots ntc_isl has (8 bytes each)
NTC_INTS	equ 1		; 0 = the platform never lets interrupts in (;@ints 0: ntc_xn's safe point has no ei)
NTC_PLATRSV	equ 0		; 1 = the platform's fixed areas (;@reserved) are Reserved in the memory map: the build goes round them (the old top-of-RAM asserts are off)
NTC_CPMGFX	equ 0		; 1 = CP/M: Graphics draws on an Amstrad CPC's screen (2.2: #C000, Plus: block 1 from common memory)
NTC_RS		macro			; the real stack: the thread position kept in ntc_ip
			move.l sp, ntc_ip
			movea.l ntc_csp, sp
			endm
NTC_TS		macro			; back to the thread
			movea.l ntc_ip, sp
			endm

ntc_start:
			move.l sp, ntc_csp		; the real stack (the library's jsr calls)
			lea main_thread, sp
			rts

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dc.l kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; main.bas 17: Mode 1
			dc.l kw_model, 1

			; main.bas 18: Print "AMSDOS test on "; System.Platform
			dc.l kw_printstrvar, str1
			dc.l kw_printnl

			; main.bas 19: Print "Devices "; FileSystem.Devices(); " - using "; FileSystem.CurrentDevice()
			dc.l kw_printstrvar, str2
			dc.l kw_printnl

			; main.bas 20: Print "Volumes "; FileSystem.Volumes(); " - using "; FileSystem.CurrentVolume()
			dc.l kw_printstrvar, str3
			dc.l kw_printnl

			; main.bas 21: Wait
			dc.l p_wait_c

			; main.bas 23: For i = 0 To 9 : a(i) = 1000 - i * 50 : Next
			dc.l kw_ztov, var_i
for1_t:
			dc.l kw_mulvl, var_i, 50, tmp2
			dc.l kw_sublv, 1000, tmp2, tmp1
			dc.l kw_aset, arr_a, var_i, tmp1
			dc.l kw_next1l, var_i, 9, for1_t
for1_e:

			; main.bas 24: r = FileSystem.Save("AMS1.DAT", VarPtr(a), 20)
			dc.l kw_ztov, var_r

			; main.bas 25: Print "Save AMS1.DAT:"; r
			dc.l kw_printstrvar, str5
			dc.l kw_printint, var_r
			dc.l kw_printnl

			; main.bas 26: r = FileSystem.Load("AMS1.DAT", VarPtr(b), 20)
			dc.l kw_ztov, var_r

			; main.bas 27: Print "Load AMS1.DAT:"; r; " -"; b(0); " ..."; b(9)
			dc.l kw_printstrvar, str6
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str7
			dc.l kw_printint, arr_b
			dc.l kw_printstrvar, str8
			dc.l kw_printint, arr_b+18
			dc.l kw_printnl

			; main.bas 28: t = Ticks
			dc.l kw_ticks, tmp0
			dc.l kw_vtov, tmp0, var_t

			; main.bas 29: Frame : Frame
			dc.l kw_frame
			dc.l kw_frame

			; main.bas 30: Print "Ticks still counting:"; IIf(Ticks <> t Or System.TicksPerSecond = 0, " yes", " NO")
			dc.l kw_ticks, tmp0
			dc.l kw_cpnevv, tmp0, var_t
			dc.l kw_ftov, tmp0
			dc.l kw_goto_ifzero, tmp0, ch2_0
			dc.l kw_strcpy, stmp0, str9
			dc.l ch2_e_go
ch2_0:
			dc.l kw_strcpy, stmp0, str10
			dc.l ch2_e_go
ch2_1:
			dc.l kw_strcpy, stmp0, str11
ch2_e:
			dc.l kw_printstrvar, str12
			dc.l kw_printstrvar, stmp0
			dc.l kw_printnl

			; main.bas 31: Print "A file that isn't there"
			dc.l kw_printstrvar, str13
			dc.l kw_printnl

			; main.bas 32: Print "(AMSDOS may print its message):"
			dc.l kw_printstrvar, str14
			dc.l kw_printnl

			; main.bas 33: r = FileSystem.Load("NOFILE.DAT", VarPtr(b), 20)
			dc.l kw_ztov, var_r

			; main.bas 34: Print "Load NOFILE.DAT:"; r; " (NotFound is -2)"
			dc.l kw_printstrvar, str16
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str17
			dc.l kw_printnl

			; main.bas 35: Wait
			dc.l p_wait_c

			; main.bas 37: Mode 2
			dc.l kw_model, 2

			; main.bas 38: Print "Mode 2 (80 columns): saving again..."
			dc.l kw_printstrvar, str18
			dc.l kw_printnl

			; main.bas 39: r = FileSystem.Save("AMS2.DAT", VarPtr(a), 20)
			dc.l kw_ztov, var_r

			; main.bas 40: Print "Save AMS2.DAT:"; r; " - this line should still be 80 columns, under the one above"
			dc.l kw_printstrvar, str20
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str21
			dc.l kw_printnl

			; main.bas 41: Wait
			dc.l p_wait_c

			; main.bas 43: Mode 1
			dc.l kw_model, 1

			; main.bas 44: Print "B = try drive B, any other key = skip"
			dc.l kw_printstrvar, str22
			dc.l kw_printnl

			; main.bas 45: Do While Inkey <> 0 : Loop
do3_t:
			dc.l kw_inkey, tmp0
			dc.l kw_cpnevl, tmp0, 0
			dc.l kw_goto_iffalse, do3_e
			dc.l do3_t_go
do3_e:

			; main.bas 46: Do : k = Inkey : Frame : Loop Until k <> 0
do4_t:
			dc.l kw_inkey, tmp0
			dc.l kw_vtov, tmp0, var_k
			dc.l kw_frame
			dc.l kw_cpnevl, var_k, 0
			dc.l kw_goto_iffalse, do4_t
do4_e:

			; main.bas 47: If k = 66 Or k = 98 Then
			dc.l kw_cpeqvl, var_k, 66
			dc.l kw_ftov, tmp0
			dc.l kw_cpeqvl, var_k, 98
			dc.l kw_ftov, tmp1
			dc.l kw_orvv, tmp0, tmp1, tmp0
			dc.l kw_goto_ifzero, tmp0, if5_1

			; main.bas 48: Print "SelectVolume B:"; FileSystem.SelectVolume("B")
			dc.l kw_printstrvar, str24
			dc.l kw_printnl

			; main.bas 49: r = FileSystem.Save("AMS3.DAT", VarPtr(a), 20)
			dc.l kw_ztov, var_r

			; main.bas 50: Print "Save B:AMS3.DAT:"; r
			dc.l kw_printstrvar, str26
			dc.l kw_printint, var_r
			dc.l kw_printnl

			; main.bas 51: r = FileSystem.Load("AMS3.DAT", VarPtr(b), 20)
			dc.l kw_ztov, var_r

			; main.bas 52: Print "Load:"; r; " -"; b(0)
			dc.l kw_printstrvar, str27
			dc.l kw_printint, var_r
			dc.l kw_printstrvar, str7
			dc.l kw_printint, arr_b
			dc.l kw_printnl

			; main.bas 53: r = FileSystem.SelectVolume("A")
			dc.l kw_ztov, var_r

			; main.bas 54: Print "Volumes now "; FileSystem.Volumes()
			dc.l kw_printstrvar, str29
			dc.l kw_printnl

			; main.bas 55: End If
if5_1:

			; main.bas 56: Print "done"
			dc.l kw_printstrvar, str30
			dc.l kw_printnl

			; main.bas 57: End
			dc.l kw_printnl0
			dc.l kw_printstrvar, str31
			dc.l kw_waitkey
			dc.l kw_stop

; ============================================================
; sub wait (turbo mode)
; ============================================================

p_wait:

			; main.bas 60: Print "Press a key"
			dc.l kw_printstrvar, str31
			dc.l kw_printnl

			; main.bas 61: Do While Inkey <> 0 : Loop
do6_t:
			dc.l kw_inkey, tmp0
			dc.l kw_cpnevl, tmp0, 0
			dc.l kw_goto_iffalse, do6_e
			dc.l do6_t_go
do6_e:

			; main.bas 62: Do : Frame : Loop Until Inkey <> 0
do7_t:
			dc.l kw_frame
			dc.l kw_inkey, tmp0
			dc.l kw_cpnevl, tmp0, 0
			dc.l kw_goto_iffalse, do7_t
do7_e:
			dc.l p_wait_r

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

ch2_e_go:			lea ch2_e, sp
			rts
do3_t_go:			lea do3_t, sp
			rts
do6_t_go:			lea do6_t, sp
			rts

p_wait_c:		; call wait
			move.l sp, p_wait_rs
			lea p_wait, sp
			rts
p_wait_r:		; end of wait
			movea.l p_wait_rs, sp
			rts

; ============================================================
; Variables
; ============================================================

; (68000: in the RAM block at the end, from $FF8000)

; numbers passed by address (read only)
			even
ntc_aptab:		dc.l 0		; AddressOf: the procedures CallAddr runs, by number
vp_arr_a:			dc.w (arr_a)&$FFFF	; VarPtr: the address, 16 bits (RAM from $FF8000)
vp_arr_b:			dc.w (arr_b)&$FFFF	; VarPtr: the address, 16 bits (RAM from $FF8000)

; ============================================================
; Strings
; ============================================================

str0:			dc.b "NEOGEO", 0
str1:			dc.b "AMSDOS test on NEOGEO", 0
str2:			dc.b "Devices 0 - using 0", 0
str3:			dc.b "Volumes 0 - using 0", 0
str4:			dc.b "AMS1.DAT", 0
str5:			dc.b "Save AMS1.DAT:", 0
str6:			dc.b "Load AMS1.DAT:", 0
str7:			dc.b " -", 0
str8:			dc.b " ...", 0
str9:			dc.b " yes", 0
str10:			dc.b " NO", 0
str11:			dc.b 0
str12:			dc.b "Ticks still counting:", 0
str13:			dc.b "A file that isn't there", 0
str14:			dc.b "(AMSDOS may print its message):", 0
str15:			dc.b "NOFILE.DAT", 0
str16:			dc.b "Load NOFILE.DAT:", 0
str17:			dc.b " (NotFound is -2)", 0
str18:			dc.b "Mode 2 (80 columns): saving again...", 0
str19:			dc.b "AMS2.DAT", 0
str20:			dc.b "Save AMS2.DAT:", 0
str21:			dc.b " - this line should still be 80 columns, under the one above", 0
str22:			dc.b "B = try drive B, any other key = skip", 0
str23:			dc.b "B", 0
str24:			dc.b "SelectVolume B:0", 0
str25:			dc.b "AMS3.DAT", 0
str26:			dc.b "Save B:AMS3.DAT:", 0
str27:			dc.b "Load:", 0
str28:			dc.b "A", 0
str29:			dc.b "Volumes now 0", 0
str30:			dc.b "done", 0
str31:			dc.b "Press a key", 0
			even

; ============================================================
; Keyword library (used)
; ============================================================

			even
;## ntc_data @shared
; ------------------------------------------------------------
; The core every program has: the thread / real stack switch
; ------------------------------------------------------------
; (NTC_RS / NTC_TS, the macros that switch to the real stack and back, are written
; by the compiler at the top of the program, before anything uses them)
ntc_next:	rts						; A6 target that continues the thread

			even
;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			NTC_RS
			jsr ntc_plat_exit
ntc_stop_loop:
			bra ntc_stop_loop		; a Mega Drive has nowhere to go back to

			even
;## kw_waitkey ntc_data ntc_plat_key
; kw_waitkey - wait for a key (Option PressAnyKeyOnEnd, before kw_stop)
kw_waitkey:
			NTC_RS
			jsr ntc_plat_getkey
			NTC_TS
			rts

			even
;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_ifzero
;kw_goto_ifzero, <var>, <label>  - branch if var = 0
kw_goto_ifzero:
			movea.l (sp)+, a0
			tst.w (a0)
			beq kw_giz_go
			addq.l #4, sp
			rts
kw_giz_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_vtov
;kw_vtov, <sourcevar>, <destvar>
kw_vtov:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), (a1)
			rts

			even
;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			movea.l (sp)+, a0
			clr.w (a0)
			rts

			even
;## kw_ftov
;kw_ftov, <destvar>  - Z flag to var: true = -1, false = 0
kw_ftov:
			seq d0
			ext.w d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

; ============================================================
; Arithmetic (16 bit, wrapping)
; ============================================================

			even
;## kw_sublv
;kw_sublv, <literal>, <var>, <destvar>  - literal - var
kw_sublv:
			move.l (sp)+, d0
			movea.l (sp)+, a1
			sub.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_mulvl
;kw_mulvl, <var>, <literal>, <destvar>
kw_mulvl:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			muls.w (a0), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## kw_orvv
kw_orvv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			or.w (a1), d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

			even
;## ntc_cmp
; tails: d0 = a, d1 = b, test a <rel> b
ntc_cmp_slt:
			cmp.w d1, d0
			slt d0
			addq.b #1, d0
			rts
ntc_cmp_sle:
			cmp.w d1, d0
			sle d0
			addq.b #1, d0
			rts
ntc_cmp_sgt:
			cmp.w d1, d0
			sgt d0
			addq.b #1, d0
			rts
ntc_cmp_sge:
			cmp.w d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_cmp_ult:
			cmp.w d1, d0
			scs d0
			addq.b #1, d0
			rts
ntc_cmp_ule:
			cmp.w d1, d0
			sls d0
			addq.b #1, d0
			rts
ntc_cmp_ugt:
			cmp.w d1, d0
			shi d0
			addq.b #1, d0
			rts
ntc_cmp_uge:
			cmp.w d1, d0
			scc d0
			addq.b #1, d0
			rts
ntc_cmp_eq:
			cmp.w d1, d0
			rts
ntc_cmp_ne:
			cmp.w d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_cpeqvl
kw_cpeqvl:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			cmp.w (a0), d1
			rts

			even
;## kw_cpnevv ntc_cmp
kw_cpnevv:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a0), d0
			move.w (a1), d1
			bra ntc_cmp_ne

			even
;## kw_cpnevl ntc_cmp
kw_cpnevl:
			movea.l (sp)+, a0
			move.w (a0), d0
			move.l (sp)+, d1
			bra ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE). An Integer address is sign extended:
; 0-32767 = the ROM's first 32K, -32768..-1 = RAM $FF8000-$FFFFFF
; (where the variables are). DEEK / DOKE need an even address.
; ============================================================

			even
;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			add.l d0, d0
			movea.l (sp)+, a1
			move.w (a1), 0(a0, d0.l)
			rts

			even
;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			moveq #0, d1
			move.b -1(a1), d1
ntc_strcpy_lp:					; a0 -> a1, at most d1 chars (d1.w > 0), then the 0
			subq.w #1, d1
			bmi ntc_strcpy_cut
ntc_strcpy_l2:
			move.b (a0)+, (a1)+
			dbeq d1, ntc_strcpy_l2
			beq ntc_strcpy_e
ntc_strcpy_cut:
			clr.b (a1)
ntc_strcpy_e:
			rts

			even
;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated text at a0, then rts (thread). On the thread.
ntc_printbuf:
			NTC_RS
			movea.l a0, a2
ntc_pb_lp:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_pb_end
			jsr ntc_plat_putc
			bra ntc_pb_lp
ntc_pb_end:
			NTC_TS
			rts

			even
;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			movea.l (sp)+, a0
			bra ntc_printbuf

			even
;## ntc_itoa ntc_data
; d0.w = signed value, a1 = buffer: the digits and a 0 (a1 ends on the 0).
; jmp (a6). Uses d0-d2, a0
ntc_itoa:
			ext.l d0
			bpl ntc_ia_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_ia_pos:
			lea ntc_ia_tmp+8, a0
			clr.b -(a0)
ntc_ia_lp:
			divu.w #10, d0
			swap d0
			addi.b #'0', d0
			move.b d0, -(a0)
			clr.w d0
			swap d0
			tst.w d0
			bne ntc_ia_lp
ntc_ia_cp:
			move.b (a0)+, (a1)+
			bne ntc_ia_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			movea.l (sp)+, a0
			move.w (a0), d0
			lea ntc_numbuf, a1
			lea kw_pi_done, a6
			bra ntc_itoa
kw_pi_done:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_printnl0 ntc_data ntc_plat_screen
;kw_printnl0  - new line unless the cursor is at the start of a line
kw_printnl0:
			tst.b ntc_curx
			beq kw_pn0_end
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
kw_pn0_end:
			rts

			even
;## kw_printnl ntc_data ntc_plat_screen
kw_printnl:
			NTC_RS
			jsr ntc_plat_newline
			NTC_TS
			rts

			even
;## kw_inkey ntc_data ntc_plat_key
;kw_inkey, <destvar>  - new key press or 0, no wait
kw_inkey:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_scankey
			NTC_TS
			andi.w #$FF, d0
			move.w d0, (a2)
			rts

			even
;## kw_model ntc_data ntc_plat_screen
;kw_model, <literal>  - clears the screen
kw_model:
			move.l (sp)+, d0
			NTC_RS
			jsr ntc_plat_mode
			NTC_TS
			rts

			even
;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame (vertical blank)
kw_frame:
			NTC_RS
			jsr ntc_plat_frame
			NTC_TS
			rts

			even
;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - the tick count (frames, 60 or 50 a second)
kw_ticks:
			movea.l (sp)+, a2
			NTC_RS
			jsr ntc_plat_ticks
			NTC_TS
			move.w d0, (a2)
			rts

; ============================================================
; String functions. Numbers are passed as the address of a word.
; Results go to a string buffer. Dest may be the same as the source.
; ============================================================

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #NTC_RAMEND, d1		; (the platform's ;@ramend, written by the compiler: $01000000 on the Mega Drive)
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "GURU 001", 0
			even

			even
;## ntc_ng_boot ntc_plat_data ntc_data ntc_plat_screen ntc_ng_snd
; ------------------------------------------------------------
; USER (the BIOS calls it, supervisor mode): request 0 / 1 back to the BIOS;
; 2 / 3: RAM cleared and the RAM block copied from the ROM, the screen, the
; sound driver's count; then user mode on the real stack and into ntc_start
; ------------------------------------------------------------
REG_P1CNT		equ $300000
REG_WATCHDOG	equ $300001
REG_SOUND		equ $320000
REG_P2CNT		equ $340000
REG_STATUSB		equ $380000
REG_SWPROM		equ $3A0013
REG_CRTFIX		equ $3A001B
REG_PALBANK0	equ $3A001F
REG_VRAMADDR	equ $3C0000
REG_VRAMRW		equ $3C0002
REG_VRAMMOD		equ $3C0004
REG_LSPCMODE	equ $3C0006
REG_IRQACK		equ $3C000C
NG_PALRAM		equ $400000
BIOS_SYSTEM_MODE	equ $10FD80
BIOS_USER_REQUEST	equ $10FDAE
NG_FIXMAP		equ $7000
NTC_USTACK		equ $0010E800			; the real stack's top
ntc_ng_user:
			move.b d0, REG_WATCHDOG
			move.b BIOS_USER_REQUEST, d0
			cmpi.b #2, d0
			bcc ntc_ng_game
			jmp $00C00444				; SYSTEM_RETURN
ntc_ng_rts:
			rts
ntc_ng_game:
			move.w #$2700, sr
			move.w #7, REG_IRQACK
			move.b d0, REG_WATCHDOG
			lea $00100000, a0			; RAM cleared, up to the real stack's top
			move.w #($E800/4)-1, d0
ntc_nb_clr:
			clr.l (a0)+
			dbra d0, ntc_nb_clr
			move.b d0, REG_WATCHDOG
			lea ntc_romend, a0			; the RAM block's first image, from the ROM
			lea ntc_ram, a1
			move.l #ntc_ramend-ntc_ram, d0
			beq ntc_nb_nodata
ntc_nb_cp:
			move.b (a0)+, (a1)+
			subq.l #1, d0
			bne ntc_nb_cp
ntc_nb_nodata:
			move.b d0, REG_WATCHDOG
			move.b #1, REG_CRTFIX		; the cartridge's fix tiles
			move.b d0, REG_PALBANK0
			move.w #0, REG_LSPCMODE		; no auto-animation timer
			move.w #1, REG_VRAMMOD
			move.w #$8000, REG_VRAMADDR	; every sprite full size
			move.w #$200-1, d0
ntc_nb_scb2:
			move.w #$0FFF, REG_VRAMRW
			dbra d0, ntc_nb_scb2
			move.w #$8200, REG_VRAMADDR	; and hidden (0 tall)
			move.w #$200-1, d0
ntc_nb_scb3:
			move.w #0, REG_VRAMRW
			dbra d0, ntc_nb_scb3
			move.w #$8400, REG_VRAMADDR	; x 0
			move.w #$200-1, d0
ntc_nb_scb4:
			move.w #0, REG_VRAMRW
			dbra d0, ntc_nb_scb4
			move.b d0, REG_WATCHDOG
			lea NG_PALRAM, a0			; the palettes: black; palette 0 colour 1 white
			move.w #$2000/4-1, d0
ntc_nb_pal:
			move.l #$80008000, (a0)+
			dbra d0, ntc_nb_pal
			move.w #$7FFF, NG_PALRAM+2
			move.b d0, REG_WATCHDOG
			move.b #40, ntc_scols
			move.b #28, ntc_srows
			move.b #$00, ntc_tattr
			jsr ntc_plat_cls
			move.b REG_SOUND, ntc_ngseq	; the sound driver's count so far
			move.l #NTC_USTACK, a0
			move.l a0, usp
			move.w #$0000, sr			; user mode, the interrupts on: A7 is now the user stack
			jmp ntc_start

; ------------------------------------------------------------
; interrupts (supervisor mode)
; ------------------------------------------------------------
; VBlank: until the game runs it is the BIOS's; then acknowledged, the
; watchdog kicked, counted, the pads read, the frame hook run
ntc_ng_vbl:
			btst #7, BIOS_SYSTEM_MODE
			bne ntc_nv_game
			jmp $00C00438				; SYSTEM_INT1
ntc_nv_game:
			move.w #4, REG_IRQACK
			move.b d0, REG_WATCHDOG
			movem.l d0-d4/a0-a1, -(sp)
			addq.w #1, ntc_ticks
			addq.w #1, ntc_vbl
			move.b REG_STATUSB, d2
			not.b d2
			move.b REG_P1CNT, d0
			not.b d0
			andi.w #$FF, d0
			btst #0, d2
			beq ntc_nv_s1
			bset #8, d0					; Start
ntc_nv_s1:
			btst #1, d2
			beq ntc_nv_e1
			bset #9, d0					; Select
ntc_nv_e1:
			move.w d0, ntc_pad1
			move.b REG_P2CNT, d0
			not.b d0
			andi.w #$FF, d0
			btst #2, d2
			beq ntc_nv_s2
			bset #8, d0
ntc_nv_s2:
			btst #3, d2
			beq ntc_nv_e2
			bset #9, d0
ntc_nv_e2:
			move.w d0, ntc_pad2
			move.l ntc_vhook, d0
			beq ntc_nv_nohook
			movea.l d0, a0
			jsr (a0)					; (keeps every register but d0-d4 / a0-a1)
ntc_nv_nohook:
			movem.l (sp)+, d0-d4/a0-a1
ntc_ng_rte:
			rte
ntc_ng_timer:
			move.w #2, REG_IRQACK
			rte

			even
;## ntc_ng_snd ntc_plat_data
; ntc_ng_snd - d0.b = a byte for the Z80's sound driver: sent, and its answer waited for (the
; driver answers each byte with its count of them; a dead or busy Z80 is given up on after a
; while). Real stack, keeps every register
ntc_ng_snd:
			movem.l d0-d1, -(sp)
			move.b d0, REG_SOUND
			move.b ntc_ngseq, d0
			addq.b #1, d0
			move.w #4000, d1
ntc_ns_wait:
			cmp.b REG_SOUND, d0
			beq ntc_ns_ok
			dbra d1, ntc_ns_wait
			move.b REG_SOUND, d0		; no answer: take what it says now
ntc_ns_ok:
			move.b d0, ntc_ngseq
			movem.l (sp)+, d0-d1
			rts

			even
;## ntc_plat_data

			even
;## ntc_plat_screen ntc_plat_data ntc_data ntc_ng_logs
; ntc_plat_putc - d0.b = character: in the fix layer at the cursor, move on, a
; new line after the last column. Real stack, keeps d2-d7 / a2-a6
ntc_plat_putc:
			movem.l d0-d2/a0, -(sp)
		ifd NTC_NGLOG
			bsr ntc_ng_log
		endif
			moveq #0, d1
			move.b ntc_cury, d1
			mulu.w #40, d1
			moveq #0, d2
			move.b ntc_curx, d2
			add.w d2, d1
			lea ntc_shadow, a0
			move.b d0, 0(a0, d1.w)
			bsr ntc_ng_cell			; d0 = char, the cursor's cell
			addq.b #1, ntc_curx
			move.b ntc_curx, d0
			cmp.b ntc_scols, d0
			bcs ntc_pc_nowrap
			move.b #1, ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			bra ntc_nl_do
ntc_pc_nowrap:
			clr.b ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			rts

; the cell at the cursor gets character d0 (the fix map: 32 cells a column, the text from row 2)
ntc_ng_cell:
			movem.l d0-d1, -(sp)
			moveq #0, d1
			move.b ntc_curx, d1
			lsl.w #5, d1
			moveq #2, d0
			add.b ntc_cury, d0
			add.w d0, d1
			addi.w #NG_FIXMAP, d1
			move.w d1, REG_VRAMADDR
			movem.l (sp)+, d0-d1
			move.l d1, -(sp)
			moveq #0, d1
			move.b ntc_tattr, d1
			lsl.w #8, d1
			move.b d0, d1
			add.w ntc_tbase, d1
			move.w d1, REG_VRAMRW
			move.l (sp)+, d1
			rts

; ntc_plat_newline - column 0, next row (scrolls at the bottom); nothing straight after a wrap
ntc_plat_newline:
		ifd NTC_NGLOG
			move.l d0, -(sp)
			moveq #10, d0
			bsr ntc_ng_log
			move.l (sp)+, d0
		endif
			tst.b ntc_wrapped
			beq ntc_nl_do
			clr.b ntc_wrapped
			rts
ntc_nl_do:
			clr.b ntc_curx
			addq.b #1, ntc_cury
			move.b ntc_cury, d0
			cmp.b ntc_srows, d0
			bcs ntc_nl_e
			subq.b #1, ntc_cury
			bra ntc_ng_scroll
ntc_nl_e:
			rts

; the text up a row: the shadow moved up, the last row cleared, the fix layer redrawn
ntc_ng_scroll:
			movem.l d0-d3/a0-a1, -(sp)
			lea ntc_shadow, a0
			lea 40(a0), a1
			move.w #40*27-1, d0
ntc_sc_mv:
			move.b (a1)+, (a0)+
			dbra d0, ntc_sc_mv
			moveq #40-1, d0
ntc_sc_cl:
			move.b #' ', (a0)+
			dbra d0, ntc_sc_cl
			bsr ntc_ng_redraw
			movem.l (sp)+, d0-d3/a0-a1
			rts

; the fix layer from the shadow (28 rows of 40): a column at a time (the fix map runs down)
ntc_ng_redraw:
			movem.l d0-d3/a0, -(sp)
			move.w #32, REG_VRAMMOD
			moveq #0, d2				; row
			moveq #0, d3
			move.b ntc_tattr, d3
			lsl.w #8, d3
ntc_rd_row:
			move.w d2, d0
			addi.w #NG_FIXMAP+2, d0
			move.w d0, REG_VRAMADDR
			lea ntc_shadow, a0
			move.w d2, d0
			mulu.w #40, d0
			adda.w d0, a0
			moveq #40-1, d1
ntc_rd_col:
			moveq #0, d0
			move.b (a0)+, d0
			bne ntc_rd_ch
			moveq #' ', d0
ntc_rd_ch:
			or.w d3, d0
			add.w ntc_tbase, d0
			move.w d0, REG_VRAMRW
			dbra d1, ntc_rd_col
			addq.w #1, d2
			cmpi.w #28, d2
			bcs ntc_rd_row
			move.w #1, REG_VRAMMOD
			movem.l (sp)+, d0-d3/a0
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_cls - clear the console, the cursor home
ntc_plat_cls:
			movem.l d0/a0, -(sp)
			lea ntc_shadow, a0
			move.w #40*28-1, d0
ntc_cls_lp:
			move.b #' ', (a0)+
			dbra d0, ntc_cls_lp
			clr.b ntc_curx
			clr.b ntc_cury
			clr.b ntc_wrapped
			bsr ntc_ng_redraw
			movem.l (sp)+, d0/a0
			rts

			even
;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_data ntc_data ntc_plat_cls
; ntc_plat_mode - d0 = mode: one text mode here (40 x 28), so it clears the screen
ntc_plat_mode:
			bra ntc_plat_cls

			even
;## ntc_ng_logs
		ifd NTC_NGLOG
; test builds (vasm -DNTC_NGLOG): what the console was given, at $10C000 on (the
; harness reads it): characters, 10 for a new line. $10DFFC: where the next goes
ntc_ng_log:
			move.l a0, -(sp)
			movea.l $0010DFFC, a0
			cmpa.l #$0010C000, a0
			bcc ntc_lg_ok
			lea $0010C000, a0
ntc_lg_ok:
			cmpa.l #$0010DFF0, a0
			bcc ntc_lg_full
			move.b d0, (a0)+
			move.l a0, $0010DFFC
ntc_lg_full:
			movea.l (sp)+, a0
			rts
		endif

			even
;## ntc_plat_key ntc_data ntc_plat_data ntc_plat_frame
; ntc_plat_scankey - d0 = the code of a button newly pressed on pad 1, or 0
ntc_plat_scankey:
			movem.l d1-d2/a0, -(sp)
			move.w ntc_pad1, d1
			move.w ntc_padseen, d2
			move.w d1, ntc_padseen
			not.w d2
			and.w d2, d1				; the new ones
			moveq #0, d0
			lea ntc_ng_keys, a0
			moveq #0, d2
ntc_sk_lp:
			btst d2, d1
			bne ntc_sk_got
			addq.w #1, d2
			cmpi.w #10, d2
			bcs ntc_sk_lp
			bra ntc_sk_e
ntc_sk_got:
			move.b 0(a0, d2.w), d0
ntc_sk_e:
			movem.l (sp)+, d1-d2/a0
			rts
ntc_ng_keys:	dc.b $F0, $F1, $F2, $F3, 'A', 'B', 'C', 'D', 13, 27
			even

; ntc_plat_getkey - wait for a button: d0 = its code
ntc_plat_getkey:
			bsr ntc_plat_scankey
			tst.b d0
			bne ntc_gk_e
			bsr ntc_plat_frame
			bra ntc_plat_getkey
ntc_gk_e:
			rts

			even
;## ntc_plat_frame ntc_plat_data
; ntc_plat_frame - wait for the next VBlank interrupt
ntc_plat_frame:
			move.l d0, -(sp)
			move.w ntc_vbl, d0
ntc_fr_lp:
			cmp.w ntc_vbl, d0
			beq ntc_fr_lp
			move.l (sp)+, d0
			rts

			even
;## ntc_plat_ticks ntc_plat_data
; ntc_plat_ticks - d0.w = frames since the start (59.19 a second)
ntc_plat_ticks:
			move.w ntc_ticks, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - before the program stops: nothing to give back (the watchdog is kicked by the
; VBlank interrupt, so a stopped program sits still rather than resetting)
ntc_plat_exit:
			rts


			even
ntc_romend:			; the end of the ROM: the RAM block's first image follows
			org $100000		; (;@ramorg: where this platform's variables are - 16 bit addresses, sign extended)
ntc_ram:
; variables
var_i:			dc.w 0
var_r:			dc.w 0
var_t:			dc.w 0
var_k:			dc.w 0
p_wait_rs:			dc.l 0
tmp0:			dc.w 0
tmp1:			dc.w 0
tmp2:			dc.w 0
			dc.b 40			; capacity
stmp0:			ds.b 41
			even
			even
ntc_csp:	dc.l 0					; the real stack (set at start)
ntc_ip:		dc.l 0					; the thread position while on the real stack
ntc_ivar:	dc.l 0					; input / inkey / ticks: dest var
ntc_sptr:	dc.l 0					; printbuf: text pointer
ntc_numbuf:	ds.b 16					; printint / long print: digits
			even
ntc_ia_tmp:	ds.b 8
			even
ntc_curx:		dc.b 0				; cursor column (0 based)
ntc_cury:		dc.b 0				; cursor row (0 based)
ntc_scols:		dc.b 40				; columns
ntc_srows:		dc.b 28				; rows
ntc_wrapped:	dc.b 0				; 1 = the last character wrapped to the next line
ntc_tattr:		dc.b $00			; the text cells' palette (high 4 bits)
ntc_ngseq:		dc.b 0				; the sound driver's count of the bytes it has taken
				dc.b 0
ntc_tbase:		dc.w 0				; added to a character for its fix tile (another font)
ntc_ticks:		dc.w 0				; frames since the start
ntc_vbl:		dc.w 0				; frames (ntc_plat_frame waits for it to move)
ntc_pad1:		dc.w 0				; pad 1's buttons now (bit 0 Up ... 7 D, 8 Start, 9 Select)
ntc_pad2:		dc.w 0
ntc_padseen:	dc.w 0				; pad 1 as Inkey last saw it (new presses only)
ntc_vhook:		dc.l 0				; a routine the VBlank interrupt runs (supervisor mode), 0 none
ntc_shadow:		ds.b 40*28			; the console's text
			even
			even
ntc_ramend:
ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_a		equ ntc_bss + 0		; 20 bytes
arr_b		equ ntc_bss + 20		; 20 bytes
ntc_bss_size	equ 40
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
